`pkg/apis/node/{v1,v1alpha1,v1beta1}` have no `+k8s:defaulter-gen=` package tag in [`doc.go`](https://github.com/kubernetes/kubernetes/blob/master/pkg/apis/node/v1/doc.go), so defaulter-gen skip generation.

If defaulter-gen is enabled `zz_generated.defaults.go` is generated as:

```go
func RegisterDefaults(scheme *runtime.Scheme) error {
	scheme.AddTypeDefaultingFunc(&nodev1.RuntimeClass{}, func(obj interface{}) { SetObjectDefaults_RuntimeClass(obj.(*nodev1.RuntimeClass)) })
	scheme.AddTypeDefaultingFunc(&nodev1.RuntimeClassList{}, func(obj interface{}) { SetObjectDefaults_RuntimeClassList(obj.(*nodev1.RuntimeClassList)) })
	return nil
}

func SetObjectDefaults_RuntimeClass(in *nodev1.RuntimeClass) {
	if in.Overhead != nil {
		corev1.SetDefaults_ResourceList(&in.Overhead.PodFixed)
	}
}

func SetObjectDefaults_RuntimeClassList(in *nodev1.RuntimeClassList) {
	for i := range in.Items {
		a := &in.Items[i]
		SetObjectDefaults_RuntimeClass(a)
	}
}
```

Should these defaults be registered?

/sig node

